struct Fenwick {
    int n;
    vector<ll> tree;
    Fenwick(int _n) {
        n = _n;
        tree.resize(n + 1);
    }
    void add(int k, ll x) {
        for (; k <= n; k += k & -k) tree[k] += x;
    }
    ll sum(int k) const {
        ll s = 0;
        for (; k > 0; k -= k & -k) s += tree[k];
        return s;
    }
    ll query(int l, int r) const {
        return sum(r) - sum(l - 1);
    }
};

