vector<int> compress(const vector<ll>& a) {
    vector<ll> xs = a;
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    vector<int> c;
    for (ll x : a) {
        c.push_back(lower_bound(xs.begin(), xs.end(), x) - xs.begin() + 1);
    }
    return c;
}

